</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define LOOP(i,j,n) for(int i=j;i<=n;i++)
#define REVERSE(i,j,n) for(int i=n;i>=j;i--)
#define ULL unsigned long long
const int MAXN=250010;
using namespace std;
namespace io {
	const int BUFSIZE=(1<<19)+1;
	char buf[BUFSIZE],*p=buf,*q=buf,obuf[BUFSIZE],*op=obuf,*oe=obuf+BUFSIZE-1,c; int flag,tp;
	char gc() {
		if(p==q) {
			q=(p=buf)+fread(buf,1,BUFSIZE,stdin);
			return p==q ? EOF : *p++;
		}
		return *p++;
	}
	template<class T> void readInt(T& x) {
		flag=1; c=gc();
		while(c<'0'||c>'9') { if(c=='-') flag=-1; c=gc(); }
		x=0;
		while(c>='0'&&c<='9') { x=x*10+(c&15); c=gc(); }
		x*=flag;
	}
}
using namespace io;
int n,k,p;
int b[MAXN];
ULL x[26][MAXN],fact[MAXN],invFact[MAXN],base,result;
ULL qpow(ULL baseVal,int y=p-2) {
	ULL res=1;
	while(y) {
		if(y&1) res=res*baseVal%p;
		baseVal=baseVal*baseVal%p;
		y>>=1;
	}
	return res;
}
ULL calc(int depth,int num) {
	if(b[num]<depth) return 0;
	if(depth==1) return x[depth][num];
	if(x[depth][num]) return x[depth][num];
	int cnt=0;
	for(int m=num&(num-1); m; m=num&(m-1))
		if(b[m]>=depth-1) {
			x[depth][num]+=calc(depth-1,m)*x[num^m][num];
			if(++cnt==18) { cnt=0; x[depth][num]%=p; }
		}
	x[depth][num]%=p;
	return x[depth][num];
}
ULL choose(int n,int m) {
	return fact[n]*invFact[m]%p*invFact[n-m]%p;
}
int main() {
	#ifndef ONLINE_JUDGE
	freopen("255x.in","r",stdin);
	freopen("255x.out","w",stdout);
	#endif
	readInt(n); readInt(k); readInt(p);
	LOOP(i,1,n) b[i]=b[i>>1]+(i&1);
	base=qpow(k,n);
	if(n&1) {
		printf("%d\n", (int)base);
		return 0;
	}
	int lim=min(k,b[n]);
	fact[0]=1;
	LOOP(i,1,n) fact[i]=fact[i-1]*i%p;
	invFact[n]=qpow(fact[n]);
	REVERSE(i,1,n-1) invFact[i]=invFact[i+1]*(i+1)%p;
	result=0;
	REVERSE(i,1,lim) result+=choose(k,i)*calc(i,n);
	base=(base - result%p*fact[n]%p + p)%p;
	printf("%lld\n", base);
	return 0;
}
